collatz.source:
# Length of the Collatz sequence starting at 27.
n = 27
steps = 0
while n != 1:
    if n % 2 == 0:
        n = n // 2
    else:
        n = 3 * n + 1
    steps += 1
print("steps", steps)

factorial.source:
# Recursive factorial of 7 and the number of trailing zeros in it.
def fact(n):
    if n <= 1:
        return 1
    return n * fact(n - 1)


value = fact(7)
zeros = 0
while value % 10 == 0:
    value = value // 10
    zeros += 1
print("fact7", fact(7), "zeros", zeros)

