caesar.source:
# Caesar cipher: encode a message, then decode it back.
def shift_char(ch, k):
    if "a" <= ch <= "z":
        base = ord("a")
        return chr((ord(ch) - base + k) % 26 + base)
    return ch


def encode(message, k):
    return "".join(shift_char(c, k) for c in message)


def decode(message, k):
    return encode(message, 26 - k)


plain = "the quick brown fox"
secret = encode(plain, 3)
back = decode(secret, 3)
print("plain ", plain)
print("secret", secret)
print("back  ", back)
print("ok", back == plain)

fibonacci.source:
# Compare an iterative and a recursive Fibonacci for the first 12 terms.
def fib_iter(n):
    a = 0
    b = 1
    for _ in range(n):
        a, b = b, a + b
    return a


def fib_rec(n):
    if n < 2:
        return n
    return fib_rec(n - 1) + fib_rec(n - 2)


values_iter = [fib_iter(k) for k in range(12)]
values_rec = [fib_rec(k) for k in range(12)]
print("iter", values_iter)
print("rec ", values_rec)
print("match", values_iter == values_rec)

fizzbuzz.source:
# Classic FizzBuzz for the numbers 1 through 20.
def classify(n):
    if n % 15 == 0:
        return "FizzBuzz"
    if n % 3 == 0:
        return "Fizz"
    if n % 5 == 0:
        return "Buzz"
    return str(n)


def main():
    results = []
    for n in range(1, 21):
        results.append(classify(n))
    print(" ".join(results))


main()

primes.source:
# Sieve of Eratosthenes: print the primes below 50.
def primes_below(limit):
    sieve = [True] * limit
    sieve[0] = False
    if limit > 1:
        sieve[1] = False
    for i in range(2, limit):
        if sieve[i]:
            for j in range(i * i, limit, i):
                sieve[j] = False
    return [i for i in range(limit) if sieve[i]]


found = primes_below(50)
print("count", len(found))
print("primes", found)

word_count.source:
# Count word frequencies in a fixed passage and show the top five.
text = """the quick brown fox jumps over the lazy dog
the dog was not amused and the fox ran away
over the hill and far away the fox went"""


def count_words(passage):
    counts = {}
    for word in passage.split():
        counts[word] = counts.get(word, 0) + 1
    return counts


freq = count_words(text)
ranked = sorted(freq.items(), key=lambda pair: (-pair[1], pair[0]))
for word, n in ranked[:5]:
    print(word, n)

